        CPU     Z8601
        ASSUME  RP:0

; Working register aliases (synthesis code)
PORT0_DAC       EQU     R0      ; Port 0 DAC
PORT1           EQU     R1      ; Port 1 readback (pitch envelope from master COP)
PORT2           EQU     R2      ; Port 2 readback (bus state: bit 2=RARC)
PORT3           EQU     R3      ; Port 3 readback (EXSLA bits 2:1, ECLK bit 3)
ZERO            EQU     R4      ; always 0 (cleared at synthesis_loop_entry)
MICRO_OP        EQU     R5      ; current micro-op dispatch address (IRQ4 target)
TIMER_LOAD      EQU     R6      ; timer reload value (written to T0 by IRQ1)
PHASE           EQU     R7      ; waveform phase accumulator / table index
ACC_HI          EQU     R8      ; accumulator high byte (frequency deviation)
ACC_LO          EQU     R9      ; accumulator low byte
WAVE_R14        EQU     R14     ; frequency step / phase increment
WAVE_R15        EQU     R15     ; previous waveform sample (interpolation)

; Memory-mapped register aliases (absolute addresses)
MODE            EQU     10h     ; mode register (from slave_ram[$FA])
SAVED_HI        EQU     11h     ; saved state (LFSR high byte / coeff running offset)
PITCH_HI        EQU     12h     ; pitch coeff high: [7:6]=EXSLA [3:0]=coeff.hi (slave_ram[$FC] + EXSLA from Port 3)
PITCH_LO        EQU     13h     ; pitch coeff low = coeff.lo (from slave_ram[$FD])
ACC2_HI         EQU     14h     ; secondary accumulator high (NOT R14!)
ACC2_LO         EQU     15h     ; secondary accumulator low (NOT R15!)
ACC3_HI         EQU     16h     ; tertiary accumulator high
ACC3_LO         EQU     17h     ; tertiary accumulator low
LOOP1_CTR       EQU     18h     ; primary loop counter
LOOP2_CTR       EQU     19h     ; secondary loop counter
PITCH_ENV       EQU     1Ah     ; pitch envelope (from Master, read via Port 1 from slave ram bus-idle address 0xff)
PROG_CTR        EQU     1Bh     ; micro-program counter (indexes $1D-$3C)
BLOCK_CTR       EQU     1Ch     ; block/phase counter (LFSR countdown / coeff toggle)
TIMER_VAL       EQU     1Dh     ; timer reload / pitch (set by synthesis_output)
MICRO_OP_NEXT   EQU     1Eh     ; micro-op chain address (set by synthesis_output)


; === Interrupt vector table (6 vectors × 2 bytes) ===
        ORG     0000h
        DW      023Ah      ; IRQ0/P3.2    → init
        DW      0EBEh      ; IRQ1/P3.3    → irq1_handler
        DW      023Ah      ; IRQ2/P3.1    → init
        DW      02E0h      ; IRQ3/P3.0    → irq3_handler
        DW      000Fh      ; IRQ4/T0      → irq4_handler
        DW      023Ah      ; IRQ5/T1      → init

        ORG     000Ch

; ============================================================
; === RESET ENTRY ($000C) ===
; ============================================================
        ORG     000Ch
reset_entry:
        JP      init

; ============================================================
; === IRQ4 — Phase Accumulator + Micro-Op Dispatch ($000F) ===
; ============================================================
        ORG     000Fh
irq4_handler:
; IRQ4 handler: fractional timer dither + micro-op dispatch.
; SPH holds an 8-bit dither pattern (from pitch_output ROM[$0232] table).
; Each IRQ4: rotate pattern left, carry adds 0 or 1 to timer reload.
; This dithers the sample rate by ±1 timer tick, giving 3 bits of
; sub-sample pitch resolution (8 dither patterns = 0/8 to 7/8 fractional).
        RL      0FEh                            ; 0FE=SPH (phase accumulator high)
        ADC     TIMER_LOAD, ZERO                ; R6 += carry (0 or 1) — dithered timer value
        LD      0F4h, TIMER_LOAD                ; 0F4=T0 (timer 0 counter)  ; reload T0 with dithered value
        LD      TIMER_LOAD, TIMER_VAL           ; restore R6 = base timer value from TIMER_VAL (reg[$1D])
        JP      @RR4                            ; dispatch to micro-op at address R4:R5 (R4=ZERO=$00)

; ============================================================
; === Micro-op: Init/silence ($19). Output $80 (center), R7=$40, R5=reg[$1E] ($0019) ===
; ============================================================
        ORG     0019h
micro_silence:
        LD      PORT0_DAC, #80h
        LD      MICRO_OP, MICRO_OP_NEXT
        LD      PHASE, #40h
        IRET

; ============================================================
; === Micro-op: 8× oversample step 1/8 ($20). OR PHASE,#$40 for @R7 indirect access ($0020) ===
; ============================================================
        ORG     0020h
micro_8x_step1:
; 8x oversampled linear scan (Mode A sub 0-5). Lowest pitch range.
; 8 IRQ4 steps per single phase advance. T=$80.
; All 8 steps output interpolated samples. Phase advances once (step 7).
; R14/R15 = working accumulators (read+written by chain).
; Chain: $20->$2C->$37->$44->$51->$5E->$6A->$76->(reg[$1E]=$20).
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #2Ch
        OR      PHASE, #40h
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 8× oversample step 2/8 ($2C). ADD R14,@R7 ($002C) ===
; ============================================================
        ORG     002Ch
micro_8x_step2:
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #37h
        LD      WAVE_R15, WAVE_R14
        ADD     WAVE_R15, @PHASE
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 8× oversample step 3/8 ($37). INC R7, lookup @R7 fwd ($0037) ===
; ============================================================
        ORG     0037h
micro_8x_step3:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, #44h
        INC     PHASE
        JR      MI, .micro_lookup_overflow
        LD      WAVE_R14, @PHASE
        IRET
.micro_lookup_overflow:                                ; 1 refs
        LD      WAVE_R14, 40h
        IRET

; ============================================================
; === Micro-op: 8× oversample step 4/8 ($44). DEC R7, lookup @R7 bwd ($0044) ===
; ============================================================
        ORG     0044h
micro_8x_step4:
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #51h
        DEC     PHASE
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        LD      WAVE_R15, WAVE_R14
        IRET

; ============================================================
; === Micro-op: 8× oversample step 5/8 ($51). Double add @R7 ($0051) ===
; ============================================================
        ORG     0051h
micro_8x_step5:
        LD      PORT0_DAC, @PHASE
        LD      MICRO_OP, #5Eh
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        IRET

; ============================================================
; === Micro-op: 8× oversample step 6/8 ($5E). Accumulate + INC R7 ($005E) ===
; ============================================================
        ORG     005Eh
micro_8x_step6:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, #6Ah
        LD      WAVE_R14, @PHASE
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        INC     PHASE
        IRET

; ============================================================
; === Micro-op: 8× oversample step 7/8 ($6A). AND PHASE,#$3F (wrap) + accumulate ($006A) ===
; ============================================================
        ORG     006Ah
micro_8x_step7:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, #76h
        AND     PHASE, #3Fh
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        IRET

; ============================================================
; === Micro-op: 8× oversample step 8/8 ($76). Indexed 40h(PHASE) lookup, R5=reg[$1E] ($0076) ===
; ============================================================
        ORG     0076h
micro_8x_step8:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, MICRO_OP_NEXT
        LD      WAVE_R14, 40h(PHASE)
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        IRET

; ============================================================
; === Micro-op: 4× oversample step 1/4 ($82). INC+AND PHASE, ADD R15+=R14 ($0082) ===
; ============================================================
        ORG     0082h
micro_4x_step1:
; 4x oversampled linear scan (Mode A sub 6). Mid-low pitch.
; 4 IRQ4 steps per phase advance. T=$80.
; Chain: $82->$8F->$9B->$A4->(reg[$1E]=$82).
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #8Fh
        INC     PHASE
        AND     PHASE, #3Fh
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 4× oversample step 2/4 ($8F). Lookup 40h(R7)→R15 ($008F) ===
; ============================================================
        ORG     008Fh
micro_4x_step2:
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #9Bh
        LD      WAVE_R15, 40h(PHASE)
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 4× oversample step 3/4 ($9B). ADD R14+=R15 ($009B) ===
; ============================================================
        ORG     009Bh
micro_4x_step3:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, #0A4h
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        IRET

; ============================================================
; === Micro-op: 4× oversample step 4/4 ($A4). Lookup 40h(R7)→R14, R5=reg[$1E] ($00A4) ===
; ============================================================
        ORG     00A4h
micro_4x_step4:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, MICRO_OP_NEXT
        LD      WAVE_R14, 40h(PHASE)
        IRET

; ============================================================
; === Micro-op: 2× oversample step 1/2 ($AC). Output R15, INC+AND PHASE, R15=waveform[PHASE] ($00AC) ===
; ============================================================
        ORG     00ACh
micro_2x_step1:
; 2x oversampled linear scan (Mode A sub 7). Mid pitch.
; 2 IRQ4 steps per phase advance. T=$80.
; Step1: output R15, INC+wrap PHASE, fetch new R15.
; Step2: output R14, interpolate R15=(R15+R14)/2, fetch new R14.
; R14/R15 are WORKING registers (sample values, not freq step!).
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #0B8h
        INC     PHASE
        AND     PHASE, #3Fh
        LD      WAVE_R15, 40h(PHASE)
        IRET

; ============================================================
; === Micro-op: 2× oversample step 2/2 ($B8). Output R14, R15=(R15+R14)/2, R14=waveform[PHASE] ($00B8) ===
; ============================================================
        ORG     00B8h
micro_2x_step2:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, MICRO_OP_NEXT
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        LD      WAVE_R14, 40h(PHASE)
        IRET

; ============================================================
; === Micro-op: 1× direct DDS ($C4). Output waveform[PHASE], PHASE+=R14, AND #$3F ($00C4) ===
; ============================================================
        ORG     00C4h
micro_1x_dds:
; 1x direct DDS (Mode A sub 8-13). High pitch range.
; 1 IRQ4 per output. Phase+=R14 per IRQ4. Timer T=R14=$01-$20.
; R14 is READ-ONLY freq step constant (set by synthesis_output from T byte).
; T and R14 are the same value: timer period = phase step = constant pitch.
; 
; WARNING: sub 0-7 use R14 as working sample; sub 8+ use R14 as freq step.
; Crossing the sub 7/8 boundary mid-note corrupts R14 interpretation.
; See WIP_ocean_crash.md.
        LD      PORT0_DAC, 40h(PHASE)
        LD      MICRO_OP, MICRO_OP_NEXT
        ADD     PHASE, WAVE_R14
        AND     PHASE, #3Fh
        IRET

; ============================================================
; === Micro-op: Variable-duty DDS ($CF→$DA→$E9). Only $CF outputs to DAC ($00CF) ===
; ============================================================
        ORG     00CFh
micro_duty_dds:
; Variable-duty DDS (Mode B). PHASE=$40-$7F = waveform table direct.
; Only $CF outputs to DAC. $DA/$E9 advance phase without output (skip zone).
; R14 = freq step (added every IRQ4), R15 = skip entry offset.
; Cycle: $CF scans $40→$7F outputting samples. When PHASE crosses $7F (MI),
;   SUB R15 adjusts skip entry. $DA/$E9 advance through $80-$FF (no output).
;   On carry (wrap past $FF): reset PHASE=$40, back to $CF.
; R15 controls duty cycle: smaller R15 = longer skip = narrower pulse.
        LD      PORT0_DAC, @PHASE
        ADD     PHASE, WAVE_R14                 ; advance phase by freq step
        JR      PL, .L_00D9                     ; PHASE < $80? → stay in output scan
        SUB     PHASE, WAVE_R15                 ; crossed $7F: adjust skip entry point by subtracting R15
        LD      MICRO_OP, #0DAh                 ; enter skip zone (no more DAC output until reset)
.L_00D9:                                ; called from: micro_duty_dds($00D3)
        IRET

; ============================================================
; === Micro-op: Duty DDS skip entry ($DA). No output. Advance until carry→$40→$CF ($00DA) ===
; ============================================================
        ORG     00DAh
micro_duty_skip1:
        SUB     PHASE, #81h                     ; map phase into skip range (SUB $81)
        ADD     PHASE, WAVE_R14                 ; advance through skip zone
        JR      NC, .skip_continue              ; carry = wrapped past $FF?
        LD      PHASE, #40h                     ; yes: reset phase to $40 (waveform table base)
        LD      MICRO_OP, #0CFh                 ; back to output scan
        IRET
.skip_continue:                                ; 1 refs
        LD      MICRO_OP, #0E9h                 ; no carry: continue skip
        IRET

; ============================================================
; === Micro-op: Duty DDS skip continue ($E9). No output. Advance until carry→$40→$CF ($00E9) ===
; ============================================================
        ORG     00E9h
micro_duty_skip2:
        ADD     PHASE, WAVE_R14                 ; keep advancing (no DAC output)
        JR      NC, .L_00F1                     ; carry?
        LD      PHASE, #40h                     ; reset to $40
        LD      MICRO_OP, #0CFh                 ; back to output scan
.L_00F1:                                ; called from: micro_duty_skip2($00EB)
        IRET

; ============================================================
; === Micro-op: Programmable-wrap DDS ($F2). Mode C sub 0-10 ($00F2) ===
; ============================================================
        ORG     00F2h
micro_wrap_dds:
        LD      PORT0_DAC, 40h(PHASE)
        CP      PHASE, WAVE_R15
        JR      NC, .L_00FC
        ADD     PHASE, WAVE_R14
        IRET
.L_00FC:                                ; called from: micro_wrap_dds($00F7)
        LD      PHASE, #00h
        LD      MICRO_OP, #0F2h
        IRET

