        DW      05F8h      ; opc $4C              → op_copy_1415_to_1617
        DW      0A72h      ; opc $50              → op_neg_1415
        DW      05F2h      ; opc $54              → op_store_r8r9_to_1617
        DW      0600h      ; opc $58              → op_store_r8r9_to_1415
        DW      0606h      ; opc $5C              → op_copy_1617_to_1415
        DW      0A58h      ; opc $60              → op_swap_1415_1617
        DW      06B2h      ; opc $64              → op_add_1617_to_r8r9
        DW      06BBh      ; opc $68              → op_add_1415_to_r8r9_sat
        DW      06D4h      ; opc $6C              → op_add_1415_to_1617
        DW      0968h      ; opc $70              → branch_dispatch
        DW      06CBh      ; opc $74              → op_add_r8r9_to_1617
        DW      06DDh      ; opc $78              → op_add_r8r9_to_1415
        DW      06E6h      ; opc $7C              → op_add_1617_to_1415
        DW      0AC3h      ; opc $80              → op_vibrato1
        DW      06EFh      ; opc $84              → op_sub_1617_from_r8r9
        DW      06F8h      ; opc $88              → op_sub_1415_from_r8r9
        DW      0711h      ; opc $8C              → op_sub_1415_from_1617
        DW      0AF1h      ; opc $90              → op_vibrato2
        DW      0708h      ; opc $94              → op_sub_r8r9_from_1617
        DW      071Ah      ; opc $98              → op_sub_r8r9_from_1415
        DW      0723h      ; opc $9C              → op_sub_1617_from_1415
        DW      0A7Bh      ; opc $A0              → op_wavetable_acc
        DW      060Fh      ; opc $A4              → op_regpair_op_08
        DW      0613h      ; opc $A8              → op_regpair_op_16
        DW      0617h      ; opc $AC              → op_regpair_op_14
        DW      086Dh      ; opc $B0              → op_mul_1617_by_imm
        DW      0748h      ; opc $B4              → op_mul_by_imm
        DW      077Eh      ; opc $B8              → op_mulimm_to_1617
        DW      07B6h      ; opc $BC              → op_mulimm_to_1415
        DW      089Dh      ; opc $C0              → op_mul_1415_by_imm
        DW      07E4h      ; opc $C4              → op_mulimm_acc_r8r9
        DW      080Fh      ; opc $C8              → op_mulimm_acc_1617
        DW      0840h      ; opc $CC              → op_mulimm_acc_1415
        DW      0740h      ; opc $D0              → op_mul_by_16
        DW      0744h      ; opc $D4              → op_mul_by_11
        DW      077Ah      ; opc $D8              → op_mul14_to_1617
        DW      07B2h      ; opc $DC              → op_mul14_to_1415
        DW      07DCh      ; opc $E0              → op_mul16_acc_r8r9
        DW      07E0h      ; opc $E4              → op_mul14_acc_r8r9
        DW      080Bh      ; opc $E8              → op_mul14_acc_1617
        DW      083Ch      ; opc $EC              → op_mul16_acc_1415
        DW      072Ch      ; opc $F0              → op_neg16_multiply
        DW      0736h      ; opc $F4              → op_neg14_multiply
        DW      076Ch      ; opc $F8              → op_neg14_mul_to_1617
        DW      07A4h      ; opc $FC              → op_neg16_mul_to_1415

; === DDS fractional frequency table (8 entries, read by dac_output_setup at $0DF8) ===
;   Each entry has N set bits for N/8 fractional timer increment.
;   Bit patterns maximize temporal spacing (minimize jitter).
;   IRQ4: RL $FE; ADC R6,R4 → carry from rotation dithers timer rate.
        ORG     0232h
        DB      00h     ; [0] 00000000  0/8 fractional
        DB      01h     ; [1] 00000001  1/8 fractional
        DB      11h     ; [2] 00010001  2/8 fractional
        DB      15h     ; [3] 00010101  3/8 fractional
        DB      55h     ; [4] 01010101  4/8 fractional
        DB      0EAh    ; [5] 11101010  5/8 fractional
        DB      0EEh    ; [6] 11101110  6/8 fractional
        DB      0FEh    ; [7] 11111110  7/8 fractional

        ORG     023Ah

; ============================================================
; === RESET / INITIALIZATION ($023A) ===
; ============================================================
        ORG     023Ah
init:                                ; 2 refs
        CLR     0FCh                            ; 0FC=FLAGS (flags register)
init_srp:                                ; 1 refs
        SRP     #00h
        LD      0FFh, #40h                      ; 0FF=SPL (stack pointer low)
        LD      0F7h, #01h                      ; 0F7=P3M (port 3 mode)
        LD      0F6h, #0Ch                      ; 0F6=P2M (port 2 mode / RARC)
        LD      0F8h, #1Ch                      ; 0F8=P01M (port 0/1 mode)
        LD      PORT0_DAC, #80h
        LD      PORT2, #05h
        LD      PORT3, #00h
init_enable_irq:                                ; 1 refs
        CLR     0FBh                            ; 0FB=IMR (interrupt mask)
        EI
        DI
        LD      0F9h, #27h                      ; 0F9=IPR (interrupt priority)
        LD      0FBh, #08h                      ; 0FB=IMR (interrupt mask)
        CLR     0FAh                            ; 0FA=IRQ (interrupt request)
        EI
spin:                                ; 2 refs
        JR      spin
ldei_chain_start:                                ; 1 refs
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        RET

; ============================================================
; === IRQ3 — RAUD Command Dispatch ($02E0) ===
; ============================================================
        ORG     02E0h
irq3_handler:
        LD      0FFh, #40h                      ; 0FF=SPL (stack pointer low)
        EI
        SRP     #00h
        LD      0F6h, #00h                      ; 0F6=P2M (port 2 mode / RARC)
        XOR     PORT2, #07h
        OR      0FAh, #02h                      ; 0FA=IRQ (interrupt request)
        LD      R11, #0F8h
        LD      R10, #10h
        LD      0F8h, #14h                      ; 0F8=P01M (port 0/1 mode)
        LDE     R13, @RR10
        TCM     R13, #04h
        JR      Z, voice_param_update
        TCM     0FCh, #02h                      ; 0FC=FLAGS (flags register)
        JR      NZ, cmd_dispatch

; ============================================================
; === First-time parameter writeback ($0302) ===
; ============================================================
        ORG     0302h
irq3_first_time:
        LD      R11, #0F5h
        LDE     R11, @RR10
        LD      R12, #02h
        LDE     @RR10, R12
        INC     R11
        LDE     @RR10, R12
        INC     R11
        LD      R12, PROG_CTR
        LDEI    @RR10, @R12
        LDEI    @RR10, @R12
        LD      R12, #08h
        LDEI    @RR10, @R12
        LDEI    @RR10, @R12
        LD      R12, #11h
.L_031C:
        LDEI    @RR10, @R12
        CP      R12, #1Eh
        JR      ULE, .L_031C
        JP      init

; ============================================================
; === Command dispatch ($0326) ===
; ============================================================
        ORG     0326h
cmd_dispatch:                                ; 1 refs
        TCM     R13, #02h
        JR      Z, stop_handler
        TCM     R13, #01h
        JR      Z, irq3_full_setup

; ============================================================
; === UPDATE — Synthesis parameter update ($0330) ===
; ============================================================
        ORG     0330h
update_path:
        LD      R11, #0F5h
        LDE     R11, @RR10
        INC     R11
        LDE     R12, @RR10
        LD      PROG_CTR, R12
        LD      R11, #0FEh
        LD      R12, #14h
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LD      R12, PORT3
        LD      0F8h, #0Ch                      ; 0F8=P01M (port 0/1 mode)
        XOR     PORT2, #07h
        LD      0F6h, #04h                      ; 0F6=P2M (port 2 mode / RARC)
        TCM     MODE, #80h
        JR      Z, .L_0356
        LD      PITCH_ENV, #00h
        JR      .L_0368
.L_0356:                                ; called from: update_path($034F)
        LD      PITCH_ENV, ACC2_LO
        CLR     ACC2_LO
        SWAP    R12
        RL      R12
        AND     R12, #0C0h
        AND     PITCH_HI, #3Fh
        OR      PITCH_HI, R12
.L_0368:                                ; called from: update_path($0354)
        CLR     LOOP1_CTR
        CLR     LOOP2_CTR
        ADD     PROG_CTR, #1Dh
        CLR     BLOCK_CTR
        JP      micro_program_interpreter

; ============================================================
; === VOICE PARAMETER UPDATE ($0374) ===
; ============================================================
        ORG     0374h
voice_param_update:                                ; 1 refs
        INC     R11
        LD      R12, #0F1h
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LD      0F8h, #1Ch                      ; 0F8=P01M (port 0/1 mode)
        XOR     PORT2, #07h
        LD      0F6h, #04h                      ; 0F6=P2M (port 2 mode / RARC)
        JP      spin

; ============================================================
; === STOP — Voice off ($0389) ===
; ============================================================
        ORG     0389h
stop_handler:                                ; 1 refs
        LD      0F8h, #1Ch                      ; 0F8=P01M (port 0/1 mode)
        XOR     PORT2, #07h
        LD      0F7h, #01h                      ; 0F7=P3M (port 3 mode)
        LD      0F6h, #0Ch                      ; 0F6=P2M (port 2 mode / RARC)
        LD      0F6h, #04h                      ; 0F6=P2M (port 2 mode / RARC)
        AND     R13, #0F8h
        ADD     R13, #05h
        LD      PORT2, R13
        LD      PORT0_DAC, #80h
        JP      init_enable_irq

; ============================================================
; === FULL VOICE SETUP ($03A5) ===
; ============================================================
        ORG     03A5h
irq3_full_setup:                                ; 1 refs
        DI
        LD      0FBh, #08h                      ; 0FB=IMR (interrupt mask)
        LD      0FCh, R13                       ; 0FC=FLAGS (flags register)
        AND     R13, #0F8h
        ADD     R13, #02h
        LD      PORT2, R13
        LD      R11, #0F9h
        LD      R12, #0Fh
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LDEI    @R12, @RR10
        LD      ACC3_HI, SAVED_HI               ; save ACC3_HI, init LFSR state to $DB
        CLR     ACC3_LO
        LD      SAVED_HI, #0DBh
        TCM     MODE, #80h                      ; mode bit 7: fixed formant? (1=freq doesn't track pitch)
        JR      Z, .pitch_env_from_acc2         ; bit 7 clear → relative formant: load pitch env from ACC2_LO + EXSLA
        LD      PITCH_ENV, #00h                 ; bit 7 set → fixed formant: no pitch tracking (clear envelope)
        JR      .load_micro_program             ; skip EXSLA setup
.pitch_env_from_acc2:                                ; 1 refs
        LD      PITCH_ENV, ACC2_LO              ; initial pitch envelope = ACC2_LO (reg[$15])
        LD      R12, PORT3                      ; read EXSLA routing from Port 3
        SWAP    R12
        RL      R12
        AND     R12, #0C0h
        AND     PITCH_HI, #3Fh                  ; merge EXSLA bits [7:6] into PITCH_HI (reg[$12])
        OR      PITCH_HI, R12
.load_micro_program:                                ; 1 refs
        LD      ZERO, #02h                      ; R4:R5 = call address for LDEI sled ($02:computed)
        LD      MICRO_OP, #0DDh                 ; R5 = $DD (end of LDEI sled)
        LD      R11, #0F4h                      ; R11 = slave_ram[$F4] (harmonic byte → sled offset)
        LDE     R12, @RR10                      ; R12 = harmonic count from slave RAM
        SUB     MICRO_OP, R12                   ; R5 -= 2*harmonics (each LDEI is 2 bytes)
        SUB     MICRO_OP, R12
        LD      R11, #0F5h                      ; R11 = slave_ram[$F5]
        LDE     R11, @RR10                      ; R11 = slave_ram[$F5] (micro-program data source pointer)
        LD      R12, #1Dh                       ; R12 = $1D (LDEI destination: reg[$1D] onward = micro-program storage)
        CALL    @RR4                            ; CALL @RR4 → computed jump into LDEI sled at $02xx, loads N bytes from slave RAM
        LD      PROG_CTR, TIMER_VAL             ; PROG_CTR = reg[$1D] (first micro-program byte = start address)
        LD      PORT0_DAC, #80h
        CLR     PHASE
        TCM     MODE, #20h
        JP      Z, synthesis_mode_a
        TCM     MODE, #10h
        JP      NZ, synthesis_mode_b
        LD      PHASE, #40h

; ============================================================
; === Mode C — Programmable-wrap DDS ($F2). MODE bits 5:4 = $10 (fall-through) ($0412) ===
; ============================================================
        ORG     0412h
synthesis_mode_c:
        LD      R11, #0F7h
        LDE     WAVE_R14, @RR10
        LD      R11, #0F6h
        LDE     MICRO_OP, @RR10
        ADD     MICRO_OP, #3Fh
        LD      ZERO, #10h
        LDE     R10, @RR4
        CLR     R11
        SUB     R10, WAVE_R14
        RCF
        RRC     R10
        RRC     R11
        INC     R10
        ADD     R10, WAVE_R15
        RRC     R10
        RRC     R11
        CLR     R13
        LD      R12, #41h
        ADD     R12, WAVE_R15
        CLR     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0447
        ADD     R11, R13
        ADC     R10, R12
.L_0447:                                ; called from: synthesis_mode_c($0441)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0457
        ADD     R11, R13
        ADC     R10, R12
.L_0457:                                ; called from: .L_0447($0451)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0467
        ADD     R11, R13
        ADC     R10, R12
.L_0467:                                ; called from: .L_0457($0461)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0477
        ADD     R11, R13
        ADC     R10, R12
.L_0477:                                ; called from: .L_0467($0471)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0487
        ADD     R11, R13
        ADC     R10, R12
.L_0487:                                ; called from: .L_0477($0481)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_0497
        ADD     R11, R13
        ADC     R10, R12
.L_0497:                                ; called from: .L_0487($0491)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_04A7
        ADD     R11, R13
        ADC     R10, R12
.L_04A7:                                ; called from: .L_0497($04A1)
        RLC     WAVE_R14
        RRC     R12
        RRC     R13
        SUB     R11, R13
        SBC     R10, R12
        JR      NC, .L_04B7
        ADD     R11, R13
        ADC     R10, R12
.L_04B7:                                ; called from: .L_04A7($04B1)
        RLC     WAVE_R14
        COM     WAVE_R14
        LD      R13, #3Eh
        LD      41h(R13), WAVE_R14
        LDE     R12, @RR4
        SUB     WAVE_R14, R12
        DEC     MICRO_OP
.L_04C6:
        LDE     R12, @RR4
        ADD     R12, WAVE_R14
        LD      40h(R13), R12
        DEC     MICRO_OP
        DJNZ    R13, .L_04C6
        LDE     R12, @RR4
        ADD     R12, WAVE_R14
        LD      40h(R13), R12
        LD      R10, #10h
        JP      synthesis_loop_entry

; ============================================================
; === Mode B — Variable-duty DDS ($CF). MODE bits 5:4 = $00 ($04DD) ===
; ============================================================
        ORG     04DDh
synthesis_mode_b:                                ; 1 refs
        LD      R11, #0F7h
        LDE     WAVE_R14, @RR10
        LD      R11, #0F6h
        LDE     R11, @RR10
        CP      WAVE_R14, #00h
        JR      Z, .L_0502
        ADD     R11, WAVE_R15
        LD      R13, WAVE_R15
.L_04EE:
        LDE     R12, @RR10
        SUB     R12, WAVE_R14
        LD      40h(R13), R12
        DEC     R11
        DJNZ    R13, .L_04EE
        LDE     R12, @RR10
        SUB     R12, WAVE_R14
        LD      40h(R13), R12
        JR      synthesis_loop_entry
.L_0502:                                ; called from: synthesis_mode_b($04E8)
        LD      R12, #40h
        LD      MICRO_OP, #0DDh
        SUB     MICRO_OP, WAVE_R15
        SUB     MICRO_OP, WAVE_R15
        CALL    @RR4
        JR      synthesis_loop_entry

; ============================================================
; === Mode A — Oversampled wavetable + direct DDS ($20-$C4). MODE bits 5:4 = $20 ($050E) ===
; ============================================================
        ORG     050Eh
synthesis_mode_a:                                ; 1 refs
        LD      R11, #0F6h
        LDE     R11, @RR10
        LD      R13, MODE
        AND     R13, #0Fh
        CP      R13, #09h
        JR      Z, .mode_a_sub9
        JR      C, .mode_a_sub_lt9
.mode_a_sub_gt9:
        LDE     WAVE_R14, @RR10
        ADD     R11, #0Fh
        LD      R13, #3Ch
.L_0525:
        LDE     WAVE_R15, @RR10
        LD      R12, WAVE_R15
        LD      40h(R13), WAVE_R15
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        LD      42h(R13), WAVE_R15
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        LD      43h(R13), WAVE_R14
        ADD     WAVE_R15, R12
        RRC     WAVE_R15
        LD      41h(R13), WAVE_R15
        LD      WAVE_R14, R12
        DEC     R11
        SUB     R13, #04h
        JR      PL, .L_0525
        JR      synthesis_loop_entry
.mode_a_sub9:                                ; 1 refs
        LDE     WAVE_R14, @RR10
        ADD     R11, #1Fh
        LD      R12, #3Ch
.L_0553:
        LDE     WAVE_R15, @RR10
        LD      42h(R12), WAVE_R15
        ADD     WAVE_R14, WAVE_R15
        RRC     WAVE_R14
        LD      43h(R12), WAVE_R14
        DEC     R11
        LDE     WAVE_R14, @RR10
        LD      40h(R12), WAVE_R14
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        LD      41h(R12), WAVE_R15
        DEC     R11
        SUB     R12, #04h
        JR      PL, .L_0553
        JR      synthesis_loop_entry
.mode_a_sub_lt9:                                ; 1 refs
        LD      R12, #40h
        CALL    ldei_chain_start

; ============================================================
; === Synthesis loop entry ($057B) ===
; ============================================================
        ORG     057Bh
synthesis_loop_entry:                                ; 5 refs
        CLR     ACC_HI
        CLR     ACC_LO
        CLR     LOOP1_CTR
        CLR     LOOP2_CTR
        CLR     BLOCK_CTR
        CLR     ZERO
        LD      MICRO_OP, #19h
        ADD     PROG_CTR, #1Ch
interpreter_reentry:                                ; 39 refs
        INC     PROG_CTR

; ============================================================
; === Micro-program interpreter ($058E) ===
; ============================================================
        ORG     058Eh
micro_program_interpreter:                                ; 5 refs
        CP      PROG_CTR, #3Dh
        JP      NC, finalize_output
        LD      R11, @PROG_CTR
        TM      R11, #03h
        JR      Z, .L_05A8
        RL      R11
        AND     R11, #1Eh
        ADD     R11, #92h
        LD      R10, #01h
        JR      .L_05B5
.L_05A8:                                ; called from: micro_program_interpreter($059A)
        RR      R11
        AND     R11, #7Eh
        CLR     R10
        ADD     R11, #0B2h
        ADC     R10, #01h
.L_05B5:                                ; called from: micro_program_interpreter($05A6)
        LDC     R12, @RR10
        INC     R11
        LDC     R13, @RR10
        JP      @RR12

; ============================================================
