        OR      0FCh, #02h                      ; 0FC=FLAGS (flags register)
        DEC     PROG_CTR
        JP      init_srp
op_swap_1415_1617:
        LD      R10, ACC3_LO
        LD      ACC3_LO, ACC2_LO
        LD      ACC2_LO, R10
        LD      R10, ACC3_HI
        LD      ACC3_HI, ACC2_HI
        LD      ACC2_HI, R10
        JP      interpreter_reentry

; ============================================================
; === Negate reg[$16:$17] ($0A69) ===
; ============================================================
        ORG     0A69h
op_neg_1617:
        COM     ACC3_HI
        COM     ACC3_LO
        INCW    ACC3_HI
        JP      interpreter_reentry
op_neg_1415:
        COM     ACC2_HI
        COM     ACC2_LO
        INCW    ACC2_HI
        JP      interpreter_reentry
op_wavetable_acc:
        LD      R10, PROG_CTR
        CP      BLOCK_CTR, ZERO
        JR      NZ, .L_0A85
        LD      BLOCK_CTR, #03h
.L_0A85:                                ; called from: op_wavetable_acc($0A80)
        ADD     R10, BLOCK_CTR
        CP      LOOP1_CTR, ZERO
        JR      NZ, .L_0A95
.L_0A8D:                                ; called from: .L_0AA7($0AB0)
        LD      LOOP1_CTR, @R10
        CP      LOOP1_CTR, ZERO
        JR      .L_0A9A
.L_0A95:                                ; called from: .L_0A85($0A8B)
        JP      MI, finalize_output.multiply
        DEC     LOOP1_CTR
.L_0A9A:                                ; called from: .L_0A8D($0A93)
        JR      Z, .L_0AA7
        DEC     R10
        ADD     ACC_LO, @R10
        DEC     R10
        ADC     ACC_HI, @R10
        JP      finalize_output.multiply
.L_0AA7:                                ; called from: .L_0A9A($0A9A)
